  'praktik_3.2': <ArticleBlock>[
    Heading('Syarat Sah & Rukun Solat'),
    Paragraph('Sebelum masuk ke urutan solat, awak perlu tahu dua perkara yang sering mengelirukan pemula: syarat sah dan rukun. Bunyinya serupa, tetapi sebenarnya berbeza.'),
