  'praktik_3.1': <QuizQuestion>[
    QuizQuestion(question: 'Berapa kali tapak tangan dibasuh semasa wuduk?', options: <String>['1 kali', '2 kali', '3 kali', '5 kali'], correctIndex: 2, explanation: 'Setiap basuhan dalam wuduk dilakukan 3 kali. Ini sunnah yang disarankan.'),
    QuizQuestion(question: 'Turutan wuduk yang betul selepas membasuh tangan ialah...', options: <String>['Kumur → hidung → muka → tangan-siku → kepala → telinga → kaki', 'Muka → kumur → hidung → kepala → tangan-siku → telinga → kaki', 'Kumur → muka → hidung → telinga → kepala → tangan-siku → kaki', 'Hidung → kumur → tangan-siku → muka → kaki → kepala → telinga'], correctIndex: 0, explanation: 'Turutan wuduk perlu berurutan: kumur → hidung → muka → tangan-siku → sapu kepala → telinga → kaki. Bayangkan menyiram air dari atas ke bawah.'),
    QuizQuestion(question: 'Sapuan ke pada kepala dilakukan berapa kali?', options: <String>['3 kali, sama seperti basuhan anggota wuduk yang lain', '1 kali sahaja, dari depan ke belakang, lalu ke depan semula', '2 kali dengan air diganti setiap sapuan', '7 kali sambil membaca niat wuduk dalam hati'], correctIndex: 1, explanation: 'Sapuan ke pala cukup sekali, dari depan ke belakang lalu ke depan semula. Berbeza daripada basuhan lain yang tiga kali.'),
    QuizQuestion(question: 'Apakah yang membatalkan wuduk?', options: <String>['Berbual dengan orang lain sebelum solat bermula', 'Makan dan minum selepas selesai berwuduk', 'Terkena debu atau kotoran dalam perjalanan ke masjid', 'Keluar sesuatu daripada kemaluan, tidur nyenyak, hilang akal'], correctIndex: 3, explanation: 'Wuduk batal bila: kencing/buang air/angin, tidur nyenyak, pengsan/mabuk, atau menyentuh kemaluan tanpa penghalang.'),
    QuizQuestion(question: 'Bila wuduk sudah, tetapi belum batal — masih boleh dipakai untuk solat seterusnya?', options: <String>['Tidak — satu wuduk sah untuk satu solat fardu sahaja', 'Boleh — selagi belum batal, wuduk itu tetap sah digunakan semula', 'Boleh, tetapi khusus untuk solat sunat sahaja, bukan fardu', 'Tidak — kecuali jarak antara solat kurang daripada satu jam'], correctIndex: 1, explanation: 'Wuduk kekal sah selagi tidak batal. Jadi wuduk Subuh, bila tidak batal, juga boleh digunakan untuk Zohor.'),
  ],
  'praktik_3.2': <QuizQuestion>[
    QuizQuestion(question: 'Apakah beza antara syarat sah dan rukun solat?', options: <String>['Syarat sah hanya berlaku pada imam; rukun untuk makmum', 'Syarat sah DIBENUA SEBELUM solat; rukun dilakukan DALAM solat', 'Rukun boleh ditinggalkan kalau lupa; syarat sah tidak boleh sepenuhnya', 'Syarat sah untuk solat fardu; rukun untuk solat sunat sahaja'], correctIndex: 1, explanation: 'Syarat sah = perkara luar solat (suci, aurat, kiblat, waktu). Rukun = perkara dalam solat (niat, takbir, ruku, sujud, dsb).'),
    QuizQuestion(question: 'Aurat lelaki semasa solat itu...', options: <String>['Seluruh tubuh kecuali muka dan tapak tangan', 'Dari bahu hingga lutut termasuk kedua lengan', 'Dari pusat hingga lutut', 'Bebas asal pakaian kemas, bersih, dan tidak telus'], correctIndex: 2, explanation: 'Lelaki: pusat hingga lutut mesti tertutup. Perempuan: seluruh tubuh kecuali muka dan tapak tangan.'),
    QuizQuestion(question: 'Berapa banyak sujud dalam satu rakaat?', options: <String>['2 kali', '1 kali', '3 kali', '4 kali'], correctIndex: 0, explanation: 'Setiap rakaat ada 2 sujud. Jadi solat 2 rakaat = 4 sujud; solat 4 rakaat = 8 sujud.'),
    QuizQuestion(question: 'Apa yang menandakan solat DIMULAI?', options: <String>['Berdiri tegak dengan menghadap kiblat', 'Membaca niat solat dalam hati dengan khusyuk', 'Membaca Surat Al-Fatihah dari ayat yang pertama', 'Takbiratul ihram — "Allahu Akbar" sambil angkat tangan'], correctIndex: 3, explanation: 'Takbiratul ihram = \'Allahu Akbar\' pertama sambil angkat tangan. Inilah tanda rasmi solat dimulai.'),
    QuizQuestion(question: 'Solat di luar waktu yang ditetapkan, sah tak?', options: <String>['Sah, kerana yang paling utama ialah niat dalam hati', 'Sah selagi belum melewati waktu solat berikutnya', 'Tidak sah — masuk waktu adalah salah satu syarat sah solat', 'Sah kalau dikerjakan berjemaah bersama imam di masjid'], correctIndex: 2, explanation: 'Masuk waktu adalah syarat sah. Solat luar waktu = tidak sah; perlu diulang di waktu yang tepat.'),
  ],
  'praktik_3.3': <QuizQuestion>[
    QuizQuestion(question: 'Berapa rakaat solat Subuh?', options: <String>['2 rakaat', '3 rakaat', '4 rakaat', '5 rakaat'], correctIndex: 0, explanation: 'Subuh = 2 rakaat. Maghrib = 3. Zohor, Asar, Isyak = 4. Mulai Subuh dahulu kalau masih belajar.'),
    QuizQuestion(question: 'Selepas Al-Fatihah di rakaat 1, apa yang dibaca?', options: <String>['Doa iftitah sebagai pembuka bacaan rakaat pertama', 'Terus ruku\' sambil mengucap Allahu Akbar', 'Dua kalimat syahadat sebelum gerakan berikutnya', 'Surah pendek, pemula disarankan baca Al-Ikhlas'], correctIndex: 3, explanation: 'Selepas Al-Fatihah, bacalah surah pendek. Al-Ikhlas disarankan untuk pemula — pendek dan mudah dihafal.'),
    QuizQuestion(question: 'Posisi ruku\' yang betul itu...', options: <String>['Bengkok dalam sehingga dahi hampir menyentuh kedua lutut', 'Tangan pegang lutut, punggung lurus, pandangan ke kaki', 'Bengkok sedikit dengan kedua tangan lurus ke bawah', 'Tangan di paha, tubuh tegak menghadap kiblat'], correctIndex: 1, explanation: 'Ruku\': bungkok, tangan pegang lutut, punggung lurus. Pandangan ke kaki, bukan ke depan.'),
    QuizQuestion(question: 'Di rakaat 3 dan 4, apa yang dibaca?', options: <String>['Al-Fatihah ditambah surah pendek seperti rakaat sebelumnya', 'Surah pendek sahaja, tanpa Al-Fatihah, agar lebih cepat selesai', 'Cuma Al-Fatihah sahaja, tanpa tambahan surah pendek', 'Bacaan tasyahud awal sebelum berdiri tegak sempurna'], correctIndex: 2, explanation: 'Di rakaat 3 dan 4, hanya baca Al-Fatihah. Tidak usah tambah surah pendek.'),
    QuizQuestion(question: 'Salam ke kanan dan ke kiri bermaksud solat...', options: <String>['Berpindah dari rakaat genap ke rakaat ganjil', 'Masuk ke segmen doa-doa tambahan sebelum zikir', 'Sedang memberi hormat kepada imam dan para makmum', 'TAMAT — ini tanda rasmi berakhirnya solat'], correctIndex: 3, explanation: 'Salam = tanda solat selesai. Putar ke kanan mengucap \'Assalamu\'alaikum warahmatullah\', lalu ke kiri.'),
  ],
  'praktik_3.4': <QuizQuestion>[
    QuizQuestion(question: 'Kapan membaca Al-Fatihah dalam solat?', options: <String>['Cukup di rakaat pertama kerana rakaat lain mengikuti', 'Di rakaat pertama dan terakhir, sebagai pembuka dan penutup', 'Boleh dilewati bila imam sudah membacanya dengan suara', 'Di setiap rakaat, wajib — tanpa Al-Fatihah rakaatnya tidak sah'], correctIndex: 3, explanation: 'Al-Fatihah wajib dibaca di SETIAP rakaat, sama imam atau sendirian. Tanpa Al-Fatihah, rakaatnya tidak sah.'),
    QuizQuestion(question: 'Bacaan ruku\' dan sujud itu...', options: <String>['Sama persis, keduanya membaca Subhana Rabbyal Adhim', 'Berbeza — ruku\' membaca \'Adhim (Yang Maha Agung), sujud membaca A\'la (Yang Maha Tinggi)', 'Bebas memilih zikir apa pun asalkan diucap tiga kali', 'Cukup membaca Allahu Akbar berulang tiga kali'], correctIndex: 1, explanation: 'Ruku\' = Subhana Rabbyal \'Adhim wa bihamdih (Maha Suci Tuhanku Yang Maha Agung). Sujud = Subhana Rabbyal A\'la wa bihamdih (Maha Suci Tuhanku Yang Maha Tinggi).'),
    QuizQuestion(question: 'Tasyahud akhir ditambah apa daripada tasyahud awal?', options: <String>['Ditambah bacaan Al-Fatihah sebagai penutup rangkaian solat', 'Ditambah doa iftitah yang dibaca pada awal solat tadi', 'Ditambah selawat Ibrahimiyah untuk Nabi Muhammad ﷺ', 'Tiadanya beza, hanya posisi duduknya yang berubah'], correctIndex: 2, explanation: 'Tasyahud akhir = tasyahud awal + selawat Ibrahimiyah. Selawat wajib dibaca di tasyahud akhir.'),
    QuizQuestion(question: 'Bacaan semasa duduk antara dua sujud itu meminta apa?', options: <String>['Pengampunan, rahmat, kecukupan, darjat, kemaafan, dan rezeki', 'Perlindungan daripada siksa kubur dan fitnah di akhir zaman', 'Keselamatan dunia akhirat untuk orang tua dan keluarga', 'Petunjuk jalan yang lurus seperti dalam Surat Al-Fatihah'], correctIndex: 0, explanation: 'Allahummaghfirli (ampun), warhamni (rahmat), wajburni (cukup), warfa\'ni (darjat), wa\'fu \'anni (kemaafan), warzuqni (rezeki).'),
    QuizQuestion(question: 'Modul ini (cheat-sheet) berguna untuk apa?', options: <String>['Bahan wajib yang perlu dihafal seluruhnya dalam sehari', 'Rujukan cepat, semua bacaan solat ada di satu tempat', 'Pengganti praktik solat bila tak sempat mengerjakannya', 'Bahan khusus bagi yang hendak menjadi imam solat berjemaah'], correctIndex: 1, explanation: 'Cheat-sheet = rujukan pantas. Simpan modul ini; awak akan kerap kembali ke sini semasa belajar solat.'),
  ],
  'praktik_3.5': <QuizQuestion>[
    QuizQuestion(question: 'Berapa rakaat solat Subuh?', options: <String>['4', '3', '2', '5'], correctIndex: 2, explanation: 'Subuh = 2 rakaat. Solat fardu dengan bilangan paling sedikit.'),
    QuizQuestion(question: 'Solat fardu yang 3 rakaat itu...', options: <String>['Maghrib', 'Subuh', 'Isyak', 'Zohor'], correctIndex: 0, explanation: 'Maghrib = 3 rakaat. Satu-satunya solat fardu yang 3 rakaat. Subuh 2, yang lain 4.'),
    QuizQuestion(question: 'Berapa jumlah rakaat solat fardu dalam sehari?', options: <String>['20', '15', '19', '17'], correctIndex: 3, explanation: '2 + 4 + 4 + 3 + 4 = 17 rakaat. Dibahagi sepanjang hari, tak banyak.'),
    QuizQuestion(question: 'Masa Asar bermula bila?', options: <String>['Bila matahari tepat berada di atas kepala kita', 'Bila bayang objek senilai panjang objek itu', 'Bila langit mula kerenahan warnanya di ufuk barat', 'Bila bayang objek dua kali panjang objeknya'], correctIndex: 1, explanation: 'Asar masuk bila bayang objek senilai panjang objeknya itu sendiri (sekitar 15:00).'),
    QuizQuestion(question: 'Kenapa Subuh cuma 2 rakaat?', options: <String>['Kerana waktunya pendek, dari fajar ke terbit matahari', 'Kerana Allah memberi keringanan buat yang baru bangun', 'Kerana dahulu Nabi ﷺ mengqashar Solat Subuh perjalanan', 'Kerana rakaatnya terisi oleh solat sunat qabliyah'], correctIndex: 0, explanation: 'Subuh cuma 2 rakaat kerana waktunya pendek. Bilangan rakaat ditetapkan Nabi ﷺ berdasarkan wahyu.'),
  ],
  'praktik_3.6': <QuizQuestion>[
    QuizQuestion(question: 'Kalau lupa sudah di rakaat keberapa, solusinya...', options: <String>['Batal solat dan mulai semula dari takbiratul ihram', 'Pilih yang kurang, tambah sujud sahwi selepas salam', 'Pilih yang lebih banyak agar rakaat tidak berkurang', 'Ikut sangkaan paling kuat lalu terus salam'], correctIndex: 1, explanation: 'Pilih yang kurang, tambah sujud sahwi selepas salam. Lupa itu manusiawi, jangan panik.'),
    QuizQuestion(question: 'Belum hafal surah pendek selain Al-Fatihah, macam mana?', options: <String>['Tangguhkan dahulu solat sampai hafal sekurang-kurangnya tiga surah', 'Baca terjemahan Indonesia sebagai ganti surah pendek', 'Tiada masalah — Al-Fatihah sahaja cukup; sisanya menyusul', 'Ulang bacaan Al-Fatihah dua kali di setiap rakaat'], correctIndex: 2, explanation: 'Al-Fatihah itu yang wajib. Surah pendek adalah tambahan, boleh surah apa saja yang dihafal. Fokus hafal Al-Fatihah dahulu.'),
    QuizQuestion(question: 'Solat qashar bermakna...', options: <String>['Memendekkan solat 4 rakaat menjadi 2, untuk musafir', 'Mempercepat gerakan solat kerana waktu begitu mendesak', 'Menggabung dua solat fardu dalam satu masa perjalanan', 'Mengganti solat yang terlewat pada waktu berikutnya'], correctIndex: 0, explanation: 'Qashar = memendekkan 4 rakaat menjadi 2. Khusus untuk musafir (perjalanan jauh). Islam tidak membebankan.'),
    QuizQuestion(question: 'Bolehkah bacaan rukun solat dengan Bahasa Indonesia?', options: <String>['Boleh, kerana Allah memahami semua bahasa hamba-Nya', 'Boleh untuk pemula, hingga hafal bacaan Arabnya', 'Tergantung kepada kebiasaan masjid dan imam di daerah', 'Tak, rukun mesti Arab; doa tambahan bebas bahasanya'], correctIndex: 3, explanation: 'Rukun = Arab (wajib, kerana Al-Quran dalam bahasa Arab dan solat distandardkan oleh Nabi). Doa tambahan = bebas bahasa apa pun.'),
    QuizQuestion(question: 'Solat belum sempurna, tetapi sudah berusaha, sahkah?', options: <String>['Belum sah sehingga semua bacaan lancar dan gerakan tepat', 'Sah hanya jika dikerjakan berjemaah di belakang imam', 'Sah, asal syarat sah terpenuhi dan rukun lengkap', 'Sah separuh, jadi pahalanya juga separuh'], correctIndex: 2, explanation: 'Solat yang tidak sempurna lebih baik daripada tidak solat sama sekali. Allah tahu awak masih belajar. Yang penting JANGAN BERHENTI.'),
  ],
  'rukun_2.1': <QuizQuestion>[
    QuizQuestion(question: '"Rukun Islam" bermaksud apa?', options: <String>['Lima amalan sunat yang digalakkan untuk Muslim yang taat', 'Lima tiang penopang yang jadi asas hidup seorang Muslim', 'Lima peraturan yang boleh dipilih mengikut kemampuan masing-masing', 'Lima peringkat rohani yang dicapai berurutan seumur hidup'], correctIndex: 1, explanation: 'Rukun bermaksud tiang penopang. Kelima-limanya wajib dan saling melengkapi, tidak boleh pilih-pilih.'),
    QuizQuestion(question: 'Apa fungsi Solat dalam kehidupan seorang Muslim?', options: <String>['Cara berbual terus dengan Allah, temujanji tetap 5 kali sehari', 'Ritual penghapus dosa yang dilakukan ketika rasa bersalah sahaja', 'Senaman regangan badan yang menyihatkan pada lima waktu berbeza', 'Kewajipan sosial supaya dianggap Muslim yang baik oleh jiran'], correctIndex: 0, explanation: 'Solat itu "temujanji" tetap awak dengan Tuhan, 5 kali sehari, tidak boleh diwakilkan atau dilangkau.'),
    QuizQuestion(question: 'Zakat berbeza daripada cukai kerana...', options: <String>['Jumlah zakat jauh lebih besar daripada cukai kerajaan', 'Zakat hanya dibayar sekali setahun pada bulan Ramadan sahaja', 'Zakat diurus terus oleh masjid tanpa peraturan tertentu', 'Zakat itu pembersihan harta, ada hak orang lain pada harta awak'], correctIndex: 3, explanation: 'Zakat bukan cukai, ia pembersihan harta. Konsepnya: harta awak bukan 100% milik awak, ada hak orang lain di dalamnya.'),
    QuizQuestion(question: 'Puasa Ramadan tujuannya bukan sekadar menahan lapar, tetapi juga...', options: <String>['Menjimatkan perbelanjaan makan sepanjang sebulan penuh', 'Membuktikan kekuatan fizikal seorang Muslim kepada orang lain', 'Melatih disiplin, empati, dan mendekatkan diri kepada Allah', 'Menjalankan tradisi turun-temurun daripada nenek moyang kita'], correctIndex: 2, explanation: 'Puasa melatih disiplin dan empati. Bukan sekadar menahan makan, tetapi juga menahan emosi, gosip, dan perkara negatif.'),
    QuizQuestion(question: 'Bila Haji wajib?', options: <String>['Sekali seumur hidup, jika mampu dari segi fizikal dan kewangan', 'Setiap lima tahun sekali bagi yang berpendapatan tetap', 'Sekali seumur hidup untuk semua Muslim tanpa pengecualian', 'Setiap tahun bagi yang tinggal berhampiran kota Makkah'], correctIndex: 0, explanation: 'Haji wajib sekali seumur hidup jika mampu. Di sana, jutaan orang dari seluruh dunia berkumpul, tidak ada bezanya kaya atau miskin.'),
  ],
  'rukun_2.2': <QuizQuestion>[
    QuizQuestion(question: 'Apa maksud "Laa ilaaha illallah"?', options: <String>['Allah itu ada dan Dialah yang mencipta seluruh alam semesta', 'Tiada satu pun yang boleh menandingi kekuasaan Allah', 'Allah Maha Besar melebihi segala sesuatu yang pernah ada', 'Tiada Tuhan yang layak disembah selain Allah'], correctIndex: 3, explanation: 'Bukan sekadar berkata \'Tuhan ada\', tetapi juga \'Dia sahaja yang layak aku sembah dan aku taati.\' Ini soal keutamaan hidup.'),
    QuizQuestion(question: 'Apa akibat melafazkan "Muhammadur Rasulullah"?', options: <String>['Wajib menghafal seluruh hadis yang diriwayatkan daripada baginda', 'Percaya baginda utusan Allah DAN berkomitmen mengikut ajarannya', 'Cukup mengenang jasa-jasanya pada setiap sambutan Maulid Nabi', 'Menjadikan baginda sebagai perantara semua doa kita kepada Allah'], correctIndex: 1, explanation: 'Kalau benar-benar percaya baginda utusan Tuhan, maka logiknya: ikut ajarannya. Seperti percaya kepada mentor, pasti ikut nasihatnya.'),
    QuizQuestion(question: '"Laa ilaaha illallah" dalam kehidupan seharian bermaksud...', options: <String>['Yang nombor satu dalam hidup ialah Allah, bukan duit atau jawatan', 'Melafazkan kalimah itu sekurang-kurangnya seratus kali setiap hari', 'Menolak semua urusan dunia dan fokus pada ibadah ritual sahaja', 'Menjauhi semua orang yang berbeza keyakinan dengan kita'], correctIndex: 0, explanation: 'Laa ilaaha illallah = keutamaan hidup. Tidak boleh takut atau bergantung kepada selain Allah melebihi-Nya.'),
    QuizQuestion(question: 'Kenapa Syahadat jadi rukun PERTAMA?', options: <String>['Kerana ia paling ringkas dan paling mudah diamalkan', 'Kerana dilafazkan Nabi ﷺ pertama kali ketika menerima wahyu', 'Kerana tanpa syahadat, empat rukun lain tidak mempunyai asas', 'Kerana urutan rukun disusun daripada yang paling ringan dahulu'], correctIndex: 2, explanation: 'Solat tanpa percaya Allah = gerakan kosong. Zakat tanpa komitmen = membuang duit. Syahadat ialah asas yang menjadikan semua ibadah mempunyai makna.'),
    QuizQuestion(question: 'Syahadat itu penghujung perjalanan rohani?', options: <String>['Ya, sebaik diucapkan, kewajipan utama seorang Muslim selesai', 'Tidak, ia titik permulaan, perjalanannya baru sahaja bermula', 'Ya, selebihnya hanya pelengkap yang tidak begitu penting', 'Bergantung pada sedalam mana kefahaman orang yang melafazkannya'], correctIndex: 1, explanation: 'Syahadat bukan garis penamat, ia garis permulaan. Komitmen seumur hidup yang baru sahaja bermula.'),
  ],
  'rukun_2.3': <QuizQuestion>[
    QuizQuestion(question: 'Inti puasa Ramadan itu bukan sekadar tahan lapar, tetapi...', options: <String>['Latihan mengawal diri, emosi, nafsu, dan keinginan', 'Membersihkan toksin di dalam tubuh selama sebulan penuh', 'Menyimpan wang belanja makan untuk persiapan hari raya', 'Membuktikan ketaatan kita kepada keluarga dan jiran sekitar'], correctIndex: 0, explanation: 'Puasa itu gimnasium jiwa. Kalau awak boleh mengawal keinginan paling asas (makan), awak juga boleh mengawal perkara yang lebih kompleks.'),
    QuizQuestion(question: 'Apa hubungan puasa dengan empati?', options: <String>['Puasa membuat kita lebih kerap berkongsi makanan lebih berbuka', 'Empati muncul kerana kita berbuka bersama keluarga setiap hari', 'Merasai lapar yang sebenar membuat kita faham keadaan orang yang tidak mampu', 'Puasa melatih kesabaran menghadapi orang yang menyakitkan hati'], correctIndex: 2, explanation: 'Dengan merasai lapar yang sebenar, awak jadi lebih faham keadaan orang yang tidak mampu makan setiap hari.'),
    QuizQuestion(question: 'Kalau sedang sakit, wajibkah berpuasa Ramadan?', options: <String>['Tetap wajib berpuasa penuh, sakit bukan alasan untuk terkecuali', 'Tidak wajib dan tidak perlu diganti kerana sudah ada keuzurannya', 'Wajib berpuasa separuh hari mengikut kemampuan fizikal masing-masing', 'Boleh tidak berpuasa, tetapi wajib qadha (ganti) selepas sembuh'], correctIndex: 3, explanation: 'Islam itu fleksibel. Sakit = boleh tidak berpuasa. Tetapi sebaik sahaja sembuh, wajib ganti pada hari lain.'),
    QuizQuestion(question: 'Warga emas yang tidak mampu berpuasa secara kekal, apa penyelesaiannya?', options: <String>['Puasanya diwakilkan oleh anak atau cucu yang masih kuat', 'Tidak wajib berpuasa, cukup membayar fidyah (memberi makan orang miskin)', 'Berpuasa separuh hari sahaja dari subuh hingga waktu Zohor', 'Menggantikan puasanya dengan memperbanyak zikir dan doa'], correctIndex: 1, explanation: 'Warga emas atau yang tidak mampu secara kekal = tidak wajib berpuasa, cukup fidyah. Islam tidak memaksakan di luar batas kemampuan.'),
    QuizQuestion(question: 'Puasa Ramadan itu hukuman atau latihan?', options: <String>['Hukuman, penebus dosa-dosa yang dilakukan sepanjang tahun', 'Kedua-duanya, bergantung kepada banyaknya dosa orang yang menjalaninya', 'Latihan, melatih disiplin, empati, dan pergantungan kepada Allah', 'Ujian fizikal tahunan untuk mengukur kekuatan iman seseorang'], correctIndex: 2, explanation: 'Puasa itu latihan, bukan hukuman. Sebulan yang menjadikan 11 bulan selebihnya lebih bermakna.'),
  ],
  'rukun_2.4': <QuizQuestion>[
    QuizQuestion(question: 'Apa maksud perkataan "zakat"?', options: <String>['Pemberian sukarela', 'Bersih dan tumbuh', 'Kewajipan harta', 'Berkongsi rezeki'], correctIndex: 1, explanation: 'Zakat bermaksud \'bersih\' dan \'tumbuh.\' Konsepnya: bersihkan hartamu daripada hak orang lain, dan hartamu jadi lebih berkat.'),
    QuizQuestion(question: 'Apa bezanya zakat, infaq, dan sedekah?', options: <String>['Zakat untuk masjid, infaq untuk fakir miskin, sedekah bebas kepada sesiapa', 'Zakat guna wang, infaq guna barang, sedekah guna tenaga atau perkhidmatan', 'Zakat wajib dengan peraturan (2.5%, nisab, haul); infaq dan sedekah sunat', 'Ketiga-tiganya sama-sama wajib, bezanya hanya pada waktu pembayarannya'], correctIndex: 2, explanation: 'Zakat = wajib dengan peraturan ketat (2.5%, nisab, haul). Infaq = sunat, berkongsi harta. Sedekah = sunat, lebih luas, malah senyuman pun sudah sedekah.'),
    QuizQuestion(question: 'Kenapa zakat boleh mengurangkan jurang sosial?', options: <String>['Kerana zakat memaksa orang kaya hidup sederhana seperti yang lain', 'Kerana semua hasil zakat digunakan untuk membina kemudahan awam', 'Kerana penerima zakat wajib menggunakan wangnya sebagai modal usaha', 'Yang ada lebih memberi 2.5% kepada yang memerlukan, kekayaan diagihkan'], correctIndex: 3, explanation: 'Zakat = sistem pengagihan kekayaan daripada Allah. Yang mampu → memberi 2.5% → yang memerlukan terbantu. Kalau semua patuh, jurang berkurang dengan ketara.'),
    QuizQuestion(question: 'Motivasi zakat yang betul itu apa?', options: <String>['Kasih sayang, percaya itu hak mereka, dan mahu hartamu bersih dan berkat', 'Takut hartanya jadi tidak berkat kalau tidak segera dikeluarkan', 'Mengharapkan pujian dan penghormatan daripada masyarakat sekitar', 'Melunaskan kewajipan supaya tidak ditagih oleh pengurus masjid'], correctIndex: 0, explanation: 'Zakat motivasinya kasih sayang, bukan paksaan. Awak memberi kerana percaya itu hak mereka dan kerana awak sayang akan hartamu sendiri, mahu yang bersih dan berkat.'),
    QuizQuestion(question: 'Sedekah itu hanya soal wang?', options: <String>['Ya, mesti berbentuk wang tunai supaya jelas nilai dan manfaatnya', 'Wang atau barang berharga, yang penting boleh dikira nilainya', 'Ya, tetapi khusus untuk keluarga boleh diganti bantuan tenaga', 'Tidak, senyuman, menolong orang, malah membuang duri dari jalan pun sedekah'], correctIndex: 3, explanation: 'Sedekah itu lebih luas daripada wang. Senyuman, menolong orang, memberi ilmu, malah membuang duri dari jalan, semuanya sedekah.'),
  ],
  'rukun_2.5': <QuizQuestion>[
    QuizQuestion(question: 'Bila haji wajib?', options: <String>['Setiap tahun sekali untuk semua Muslim yang badannya sihat', 'Sekali seumur hidup, jika mampu dari segi fizikal dan kewangan', 'Dua kali seumur hidup: semasa muda dan selepas bersara', 'Bila-bila masa asalkan sudah ada simpanan, tanpa syarat lain'], correctIndex: 1, explanation: 'Haji wajib sekali seumur hidup TETAPI hanya kalau mampu. Kalau belum mampu, tidak berdosa.'),
    QuizQuestion(question: 'Kenapa semua jemaah haji memakai pakaian putih yang sama (ihram)?', options: <String>['Kerana warna putih paling tahan panas dalam cuaca gurun Arab', 'Supaya petugas mudah membezakan jemaah daripada penduduk tempatan', 'Mengikut tradisi pakaian bangsa Arab sejak sebelum zaman Islam', 'Simbol kesetaraan, di hadapan Allah semua sama, tiada beza harta'], correctIndex: 3, explanation: 'Ihram = pakaian putih tanpa jenama. Presiden, buruh, ahli perniagaan, semua sama. Yang membezakan di sisi Allah bukan harta, tetapi ketakwaan.'),
    QuizQuestion(question: 'Apa makna tawaf (mengelilingi Kaabah 7 kali)?', options: <String>['Mengenang Kaabah sebagai bangunan paling tua di muka bumi', 'Mengenang perjalanan hijrah Nabi ﷺ dari Makkah ke Madinah', 'Hidup mesti berpusat pada Allah, seperti planet yang mengorbit', 'Melatih fizikal jemaah sebelum rangkaian ibadah yang lebih berat'], correctIndex: 2, explanation: 'Tawaf = simbol hidup berpusat pada Allah. Seperti planet yang mengorbit, hidupmu mesti berputar di sekeliling-Nya.'),
    QuizQuestion(question: 'Kalau belum mampu haji dari segi kewangan, apa yang berlaku?', options: <String>['Tidak wajib, Allah tidak membebankan di luar batas kemampuan', 'Tetap wajib pergi dengan cara mengangsur atau meminjam', 'Dosa kecil yang boleh dihapuskan dengan memperbanyak sedekah', 'Kewajipannya berpindah kepada anak yang wajib menghajikan ibu bapanya'], correctIndex: 0, explanation: 'Haji hanya wajib kalau mampu. Kalau belum mampu, tidak berdosa. Keluarga di rumah mesti tetap tercukupi dahulu.'),
    QuizQuestion(question: 'Apa makna melontar jumrah semasa haji?', options: <String>['Menghalau gangguan jin yang berkumpul di lembah kota Mina', 'Melambangkan peperangan melawan musuh-musuh Islam zaman dahulu', 'Membuang sial dan penyakit supaya tidak terbawa pulang ke rumah', 'Simbol menolak godaan syaitan, daripada yang kecil hingga yang besar'], correctIndex: 3, explanation: 'Melontar jumrah = simbol menolak godaan syaitan. Daripada jumrah kecil, sederhana, hingga besar, semakin lama semakin tegas penolakannya.'),
  ],
  'why_4.1': <QuizQuestion>[
    QuizQuestion(question: 'Menjadi Muslim kerana keluarga bermaksud...', options: <String>['Iman itu sebenarnya tak sah di sisi agama', 'Cukup mewarisi sahaja tanpa perlu tanya lagi nanti', 'Awak tak perlu lagi memeriksa keyakinan sendiri', 'Awal yang baik untuk memilih iman lebih sedar'], correctIndex: 3, explanation: 'Warisan keluarga boleh jadi permulaan yang baik; iman tetap perlu difahami dan dipilih dengan sedar.'),
    QuizQuestion(question: 'Sikap sihat terhadap soalan tentang Islam ialah...', options: <String>['Simpan sahaja, ragu-ragu mesti salah', 'Mengolok orang yang berbagai-bagai bertanya', 'Mencari jawab dengan jujur dan rendah hati', 'Sukasuka ambil jawapan yang paling sedap'], correctIndex: 2, explanation: 'Soalan yang jujur boleh menjadi pintu belajar yang baik.'),
    QuizQuestion(question: 'QS. Al-Isra 17:36 mengingatkan agar kita...', options: <String>['Tak mengikut apa-apa tanpa dasar ilmu dahulu', 'Berhenti belajar agama di situ sahaja', 'Sentiasa mengikut kebiasaan keluarga di rumah', 'Menolak setiap nasihat yang datang daripada keluarga'], correctIndex: 0, explanation: 'Ayat ini menggalakkan sikap berilmu, bukan mengikut tanpa dasar.'),
    QuizQuestion(question: 'Langkah permulaan yang disarankan artikel ialah...', options: <String>['Memenangi setiap perbahasan yang muncul', 'Menyimpan satu soalan yang jujur', 'Menghafal semua jawapan yang tersedia', 'Menilai kualiti iman orang lain di sekeliling'], correctIndex: 1, explanation: 'Satu soalan yang jujur ialah permulaan belajar yang sebenar.'),
    QuizQuestion(question: 'Iman yang dipilih dengan sedar bermaksud...', options: <String>['Membenci seluruh didikan masa kecil awak', 'Menolak semua tradisi yang diwarisi keluarga', 'Berhenti mencari guru dan harapkan diri sendiri', 'Menghargai warisan yang baik sambil memahaminya'], correctIndex: 3, explanation: 'Belajar dengan sedar tidak mengharuskan kita merendahkan keluarga atau tradisi yang baik.'),
  ],
  'why_4.10': <QuizQuestion>[
    QuizQuestion(question: 'Iman yang dewasa bukan bererti...', options: <String>['Sentiasa ingin belajar perkara baharu', 'Berhenti pernah salah atau tersesat lagi', 'Justru nampak lebih rendah hati', 'Lebih sedia memikul tanggungjawab penuh'], correctIndex: 1, explanation: 'Manusia tetap boleh salah dan ragu; kemasakan ternampak pada tindak balasnya.'),
