  'praktik_3.6': <QuizQuestion>[
    QuizQuestion(question: 'Kaçıncı rekâtta olduğunu unutursan çözüm nedir?', options: <String>['Namazı iptal edip tekbiratül ihramdan yeniden başlamak', 'Küçük sayıyı al, selamdan sonra sehiv secdesi ekle', 'Rekât eksik kalmasın diye büyük sayıyı al', 'En iyi tahminini izle sonra doğruca selama git'], correctIndex: 1, explanation: 'Küçük sayıyı al, selamdan sonra sehiv secdesi ekle. Unutmak insana mahsustur, panik yok.'),
    QuizQuestion(question: 'Al-Fatiha dışında hiçbir kısa sure ezberleyemedin, ne yapmalı?', options: <String>['En az üç kısa sure öğrenene kadar namazı ertelemek', 'Yerine Endonezce çevirisini okumak', 'Sorun değil, tek başına Al-Fatiha yeterli; gerisi sonra gelir', 'Her rekâtta Al-Fatiha\'yı iki kez tekrarlamak'], correctIndex: 2, explanation: 'Farz olan Al-Fatiha\'dır. Kısa sure bir ek, ezberlediğin herhangi bir sure olur. Önce Al-Fatiha\'ya odaklan.'),
    QuizQuestion(question: 'Kasr namazı ne demektir?', options: <String>['Özellikle yolcular için 4 rekâtlık namazı 2\'ye kısaltmak', 'Vakit dar olduğu için namaz hareketlerini hızlandırmak', 'İki farz namazı tek yolculuk vaktinde birleştirmek', 'Kazaya kalan namazı bir sonraki vaktinde tekrar kılmak'], correctIndex: 0, explanation: 'Kasr = 4 rekâtı 2\'ye kısaltmak. Özellikle misafir için (uzun yolculuklar). İslam aşırı yüklemez.'),
    QuizQuestion(question: 'Rükünlerin okunuşları Endonezce olabilir mi?', options: <String>['Evet, Allah kullarının her dilini anlar', 'Yeni başlayanlar için evet, Arapçayı ezberleyene kadar', 'Her caminin ve imamın yerel alışkanlığına bağlı', 'Hayır, rükünler Arapça olmalı; ek dualar her dilde serbest'], correctIndex: 3, explanation: 'Rükünler = Arapça (farz; Kur\'an Arapçadır ve namaz Peygamber tarafından standartlaştırılmıştır). Ek dualar = herhangi bir dil.'),
    QuizQuestion(question: 'Çabaya rağmen namaz hâlâ kusurlu, geçerli mi?', options: <String>['Tüm okunuşlar akıcı ve hareketler tam olana kadar geçerli değil', 'Sadece imamın arkasında cemaatle kılınınca geçerli', 'Geçerli, yeter ki geçerlilik şartları yerine gelsin ve rükünler tam olsun', 'Yarı geçerli, dolayısıyla verilecek sevap da yarıya iner'], correctIndex: 2, explanation: 'Kusurlu bir namaz, hiç namaz kılmamaktan iyidir. Allah öğrenmekte olduğunu biliyor. Kilit nokta: DURMA.'),
  ],
  'rukun_2.1': <QuizQuestion>[
    QuizQuestion(question: '"İslam\'ın Şartları" ne demek?', options: <String>['İtaatkâr Müslüman için beş gönüllü amel', 'Müslümanın hayat temelini oluşturan beş destek sütunu', 'Herkesin gücüne göre seçebileceği beş kural', 'Ömür boyu sırayla ulaşılan beş manevi seviye'], correctIndex: 1, explanation: '"Şart" destek sütunu demektir. Beşi farzdır ve birbirini tamamlar; seçip beğenemezsin.'),
    QuizQuestion(question: 'Namazın bir Müslümanın hayatındaki yeri nedir?', options: <String>['Allah ile doğrudan konuşma; günde 5 vakit düzenli buluşma', 'Sadece suçlu hissedince yapılan günah silme ritüeli', 'Günün beş farklı vaktinde yapılan beden esnetme hareketi', 'Komşular iyi Müslüman sansın diye yapılan sosyal zorunluluk'], correctIndex: 0, explanation: 'Namaz, Tanrı ile kurulan düzenli buluşmadır; günde 5 kez, devredilemez, atlanamaz.'),
    QuizQuestion(question: 'Zekât vergiden şu yönüyle ayrılır:', options: <String>['Zekâtın miktarı devlet vergisinden çok daha fazladır', 'Zekât yılda yalnızca bir kez, Ramazan\'da ödenir', 'Zekât cami tarafından yönetilir ve kuralı yoktur', 'Zekât serveti arındırır; başkalarının ondan hakkı vardır'], correctIndex: 3, explanation: 'Zekât vergi değil, servet arındırıcısıdır. Mantık: servetin %100 senin değil, başkalarının da payı var.'),
    QuizQuestion(question: 'Ramazan orucunun amacı sadece açlığa dayanmak değil, aynı zamanda:', options: <String>['Bir ay boyunca yemek harcamasını kısmak', 'Bir Müslümanın beden gücünü başkalarına göstermek', 'Disiplin, empati ve Allah\'a yakınlığı geliştirmek', 'Atalardan kalan bir geleneği sürdürmek'], correctIndex: 2, explanation: 'Oruç disiplin ve empatiyi geliştirir. Sadece yemekten değil; duygulardan, dedikodudan ve olumsuzluktan da uzak durmaktır.'),
    QuizQuestion(question: 'Hac ne zaman farzdır?', options: <String>['Maddi ve bedeni gücü yetiyorsa, ömürde bir kez', 'Düzenli geliri olanlar için beş yılda bir', 'Her Müslüman için istisnasız ömürde bir kez', 'Mekke şehrine yakın yaşayanlar için her yıl'], correctIndex: 0, explanation: 'Hac, gücü yetiyorsa ömürde bir kez farzdır. Orada dünyanın her yerinden milyonlarca kişi toplanır; zengin-fakir ayrımı yoktur.'),
  ],
  'rukun_2.2': <QuizQuestion>[
    QuizQuestion(question: '"Lâ ilâhe illallah" ne anlama gelir?', options: <String>['Allah vardır ve tüm evreni O yarattı', 'Allah\'ın kudretine hiçbir şey denk olamaz', 'Allah, var olmuş her şeyden daha büyüktür', 'Allah\'tan başka ibadete layık ilah yoktur'], correctIndex: 3, explanation: 'Sadece "Tanrı var" demek değil, "yalnız O, ibadetime ve itaatime layıktır" demek. Bu, hayattaki öncelikler meselesi.'),
    QuizQuestion(question: '"Muhammedün Rasûlullah" demenin sonucu nedir?', options: <String>['Ondan rivayet edilen tüm hadisleri ezberlemek', 'Onun Allah\'ın elçisi olduğuna inanmak VE öğretilerine uymaya söz vermek', 'Sadece her Mevlid kutlamasında onun faziletlerini anmak', 'Allah\'a yaptığımız her duada onu aracı kılmak'], correctIndex: 1, explanation: 'Onun gerçekten Tanrı\'nın elçisi olduğuna inanıyorsan, mantıklısı öğretilerine uymaktır. Bir mentora güvenmek, onun tavsiyesine uymak demektir.'),
    QuizQuestion(question: '"Lâ ilâhe illallah" günlük hayatta şu demektir:', options: <String>['Hayatta bir numara Allah\'tır, para ya da makam değil', 'Bu cümleyi her gün en az yüz kez okumak', 'Tüm dünya işlerini reddedip yalnızca ibadete odaklanmak', 'İnancı bizden farklı olan herkesten uzak durmak'], correctIndex: 0, explanation: 'Lâ ilâhe illallah = hayat önceliği. Allah\'tan başkasından O\'ndan korktuğundan daha çok korkmamalı, O\'ndan başkasına daha çok güvenmemelisin.'),
    QuizQuestion(question: 'Şehadet neden İLK rükündür?', options: <String>['Çünkü en kısa ve uygulaması en kolay olanıdır', 'Çünkü Peygamber ﷺ onu vahiy alırken ilk kez söyledi', 'Çünkü şehadet olmadan diğer dört rükün temelsizdir', 'Çünkü rükünler en hafiften ağıra doğru sıralanmıştır'], correctIndex: 2, explanation: 'Allah\'a inanmadan namaz = boş hareket. Taahhütsüz zekât = para israfı. Şehadet, tüm ibadetlere anlam kazandıran temeldir.'),
    QuizQuestion(question: 'Şehadet ruhsal yolculuğun sonu mudur?', options: <String>['Evet, söylendiği an Müslümanın temel yükümlülüğü tamamlanır', 'Hayır, bu başlangıç noktası, yolculuk daha yeni başladı', 'Evet, gerisi çok da önemsiz tamamlayıcı detaylar', 'Söyleyen kişinin anlayışının derinliğine bağlı'], correctIndex: 1, explanation: 'Şehadet bitiş çizgisi değil, başlangıç çizgisidir. Daha yeni başlayan bir ömür boyu taahhüt.'),
  ],
  'rukun_2.3': <QuizQuestion>[
    QuizQuestion(question: 'Ramazan orucunun özü sadece açlığa dayanmak değil, aynı zamanda:', options: <String>['Duyguları, arzuları ve dürtüleri kontrol etme eğitimi', 'Bir ay boyunca bedendeki toksinleri atmak', 'Bayram günü hazırlığı için market parası biriktirmek', 'Aileye ve komşulara itaatimizi kanıtlamak'], correctIndex: 0, explanation: 'Oruç ruhun spor salonudur. En temel arzunu (yemeği) kontrol edebiliyorsan, daha karmaşıklarını da edebilirsin.'),
    QuizQuestion(question: 'Oruç ile empati arasındaki bağ nedir?', options: <String>['Oruç, iftar artığı yemekleri daha sık paylaşmamızı sağlar', 'Empati, her gün aileyle iftar açtığımız için doğar', 'Gerçek açlığı hissetmek, yoksulun ne yaşadığını anlamamızı sağlar', 'Oruç, can sıkan insanlara karşı sabrı öğretir'], correctIndex: 2, explanation: 'Gerçek açlığı hissederek, her gün yemek bulamayanların içinde bulunduğu durumu anlarsın.'),
    QuizQuestion(question: 'Hasta olan biri Ramazan\'da oruç tutmak zorunda mı?', options: <String>['Tamamen tutmalıdır; hastalık mazeret değildir', 'Yükümlü değildir ve kaza da gerekmez, geçerli mazereti var', 'Herkesin beden gücüne göre yarım gün oruç tutar', 'Tutmayabilir, ama iyileştikten sonra kaza etmesi gerekir'], correctIndex: 3, explanation: 'İslam esnektir. Hastalık varsa tutmayabilir. Ama iyileştikten sonra başka günlerde kaza etmesi gerekir.'),
    QuizQuestion(question: 'Kalıcı olarak oruç tutamayan yaşlı biri ne yapar?', options: <String>['Orucu güçlü çocukları ya da torunları tarafından yerine getirilir', 'Oruçla yükümlü değildir; fidye ödemesi yeter (yoksulu doyurmak)', 'Sadece sabahtan öğleye kadar yarım gün oruç tutar', 'Yerine bol bol zikir ve dua eder'], correctIndex: 1, explanation: 'Yaşlı olup kalıcı olarak gücü yetmeyen yükümlü değildir; fidye yeter. İslam kapasitenin üstünde zorlamaz.'),
    QuizQuestion(question: 'Ramazan orucu ceza mıdır, eğitim mi?', options: <String>['Ceza; tüm yıl işlenen günahların kefareti', 'İkisi de; kişinin işlediği günah sayısına bağlı', 'Eğitim; disiplin, empati ve Allah\'a bağlılığı geliştirir', 'Yıllık beden sınavı; iman gücünü ölçer'], correctIndex: 2, explanation: 'Oruç ceza değil, eğitimdir. Diğer on bir ayı anlamlı kılan bir ay.'),
  ],
  'rukun_2.4': <QuizQuestion>[
    QuizQuestion(question: '"Zekât" kelimesi ne anlama gelir?', options: <String>['Gönüllü bağış', 'Temiz ve büyüyen', 'Mal yükümlülüğü', 'Rızkı paylaşmak'], correctIndex: 1, explanation: 'Zekât \'temiz\' ve \'büyüyen\' demektir. Konsept: malını başkalarının hakkından temizlersin ve malın daha bereketli olur.'),
    QuizQuestion(question: 'Zekât, infak ve sadaka arasındaki fark nedir?', options: <String>['Zekât camiye, infak yoksula, sadaka kime olursa olsun', 'Zekât parayla, infak eşyayla, sadaka emek ya da hizmetle', 'Zekât kurallı farzdır (%2,5, nisab, havl), infak ve sadaka sünnettir', 'Üçü de farzdır, fark yalnızca ödeme zamanındadır'], correctIndex: 2, explanation: 'Zekât = sıkı kurallı farz (%2,5, nisab, havl). İnfak = sünnet, mal paylaşımı. Sadaka = sünnet ve daha geniş, bir gülümseme bile sadakadır.'),
    QuizQuestion(question: 'Zekât neden toplumsal eşitsizliği azaltabilir?', options: <String>['Çünkü zekât zengini herkes gibi sade yaşamaya zorlar', 'Çünkü tüm zekât geliri kamusal tesislere gider', 'Çünkü zekât alan kişi parayı işletme sermayesi olarak kullanmak zorundadır', 'Çok olan %2,5\'i ihtiyaç sahibine verir, servet dağılır'], correctIndex: 3, explanation: 'Zekât = Allah\'ın servet dağıtım sistemi. Gücü yeten, %2,5 verir, ihtiyaç sahibi yardım görür. Herkes uyarsa eşitsizlik belirgin biçimde azalır.'),
    QuizQuestion(question: 'Zekâtın doğru motivasyonu nedir?', options: <String>['Sevgi, onların hakkı olduğuna inanmak ve malının temiz ve bereketli olmasını istemek', 'Malın hemen verilmezse bereketini kaybedeceği korkusu', 'Çevreden övgü ve saygı beklemek', 'Cami görevlileri istemesin diye yükümlülüğü yerine getirmek'], correctIndex: 0, explanation: 'Zekâtın motivi zorlama değil, sevgidir. Verirsin çünkü bunun onların hakkı olduğuna inanırsın ve kendi malını seversin, onun temiz ve bereketli olmasını istersin.'),
    QuizQuestion(question: 'Sadaka sadece parayla mı ilgilidir?', options: <String>['Evet, değeri ve faydası belli olsun diye nakit olmalıdır', 'Para ya da değerli eşya, önemli olan değerinin hesaplanabilmesidir', 'Evet, ama aile için emek yardımına dönüşebilir', 'Hayır, bir gülümseme, birine yardım, hatta yoldan diken kaldırmak bile sadakadır'], correctIndex: 3, explanation: 'Sadaka paradan daha geniştir. Gülümseme, birine yardım, ilim öğretmek, hatta yoldan diken kaldırmak, hepsi sadakadır.'),
  ],
  'rukun_2.5': <QuizQuestion>[
    QuizQuestion(question: 'Hac ne zaman farzdır?', options: <String>['Beden sağlığı yerinde olan her Müslüman için yılda bir kez', 'Ömürde bir kez, bedenen ve maddi olarak gücü yetiyorsa', 'Ömürde iki kez: gençken ve emekli olduktan sonra', 'Yeter ki birikim olsun, başka şart olmadan istediğin zaman'], correctIndex: 1, explanation: 'Hac ömürde bir kez farzdır AMA yalnızca gücü yetiyorsa. Henüz gücün yetmiyorsa günah yok.'),
    QuizQuestion(question: 'Neden tüm hacılar aynı beyaz kıyafeti (ihramı) giyer?', options: <String>['Çünkü beyaz, Arap çölünün sıcağına en iyi dayanan renktir', 'Görevliler hacıları yerli halktan kolayca ayırt edebilsin diye', 'İslam öncesi Arapların kıyafet geleneğini sürdürmek için', 'Eşitliğin sembolü; Allah\'ın katında herkes eşit, mal farkı yok'], correctIndex: 3, explanation: 'İhram = markasız beyaz kıyafet. Cumhurbaşkanı, işçi, işletmeci, hepsi aynı. Allah\'ın katında ayıran şey mal değil, takvadır.'),
    QuizQuestion(question: 'Tavafın (Kâbe\'nin etrafını 7 kez dolaşmanın) anlamı nedir?', options: <String>['Kâbe\'yi yeryüzünün en eski binası olarak anmak', 'Peygamberin ﷺ Mekke\'den Medine\'ye hicretini anmak', 'Hayat Allah merkezli olmalıdır, yörüngedeki gezegenler gibi', 'Daha ağır ibadet dizilerinden önce hacıların bedenini çalıştırmak'], correctIndex: 2, explanation: 'Tavaf = hayatın Allah merkezli olmasının sembolü. Yörüngede dönen gezegenler gibi, hayatın da O\'nun etrafında dönmelidir.'),
    QuizQuestion(question: 'Birinin hacca maddi gücü yetmiyorsa ne olur?', options: <String>['Farz değildir, Allah gücün üstünde yük yüklemez', 'Yine de taksitle ya da borç alarak gitmek zorundadır', 'Bol sadaka ile silinebilecek küçük bir günah', 'Yükümlülük, anneye babaya hac borcu olan çocuklara geçer'], correctIndex: 0, explanation: 'Hac yalnızca gücü yetiyorsa farzdır. Yetmiyorsa günah yok. Önce evdeki ailenin geçimi güvence altında olmalıdır.'),
    QuizQuestion(question: 'Hacda şeytan taşlamanın anlamı nedir?', options: <String>['Mina vadisinde toplanan cin katmanlarını kovmak', 'İslam\'ın kadim düşmanlarına karşı savaşı simgelemek', 'Uğursuzluk ve hastalıkları eve taşınmasın diye atmak', 'Küçükten büyüğe şeytanın vesvesesini reddetmenin sembolü'], correctIndex: 3, explanation: 'Şeytan taşlama = şeytanın vesvesesini reddetmenin sembolü. Küçük, orta ve büyük taştan büyüğe doğru reddediş her seferinde daha kararlı olur.'),
  ],
  'why_4.1': <QuizQuestion>[
